187→	if data, readErr := os.ReadFile(ackPath); readErr == nil {
188→		if err := json.Unmarshal(data, &acks); err != nil {
189→			t.Fatalf("parse gemini acknowledgments: %v", err)
190→		}
191→	} else if !errors.Is(readErr, os.ErrNotExist) {
192→		t.Fatalf("read gemini acknowledgments: %v", readErr)
193→	}
